//! Byte-for-byte conformance against `reference/vectors/04-pcs/`
//! (`merkle.json`, `ntt.json`, `ring_switch.json`, `ligerito.json`),
//! generated by `reference/gen_vectors_04.py`. Mirrors
//! `reference/tests/test_pcs_vectors.py`, plus the ring-switching vector
//! (which the Python vector test does not consume).

use std::path::PathBuf;

use om_field::K;
use om_pcs::LigeritoPCS;
use om_pcs::ligerito::LigeritoParams;
use om_pcs::merkle::MerkleTree;
use om_pcs::ntt;
use om_pcs::pcs::Pcs;
use om_pcs::ring_switch as rsw;
use om_sumcheck::SumcheckProof;
use om_transcript::{Hasher, Transcript};
use serde_json::Value;

fn load(name: &str) -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../reference/vectors/04-pcs")
        .join(name);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {path:?}: {e}"));
    serde_json::from_str(&text).unwrap()
}

fn k(v: &Value) -> K {
    K::from_hex(v.as_str().unwrap()).unwrap()
}

fn ks(v: &Value) -> Vec<K> {
    v.as_array().unwrap().iter().map(k).collect()
}

fn hexes(xs: &[K]) -> Vec<String> {
    xs.iter().map(|x| x.to_hex()).collect()
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_str().unwrap().to_string())
        .collect()
}

fn bytes_from_hex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2));
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap())
        .collect()
}

fn to_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn usizes(v: &Value) -> Vec<usize> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as usize)
        .collect()
}

#[test]
fn merkle_vectors() {
    let v = load("merkle.json");
    for vec in v["vectors"].as_array().unwrap() {
        let h = Hasher::from_profile_id(vec["hash"].as_str().unwrap().as_bytes()).unwrap();
        let leaves: Vec<Vec<u8>> = strings(&vec["leaves"])
            .iter()
            .map(|s| bytes_from_hex(s))
            .collect();
        let t = MerkleTree::new(h, &leaves);
        assert_eq!(to_hex(&t.root()), vec["root"].as_str().unwrap());
        let auth: Vec<String> = t
            .open(&usizes(&vec["indices"]))
            .unwrap()
            .iter()
            .map(|a| to_hex(a))
            .collect();
        assert_eq!(auth, strings(&vec["auth"]));
    }
}

#[test]
fn ntt_vectors() {
    let v = load("ntt.json");
    // what_beta table: row i holds what_beta(i, b) for b = i..6.
    for (i, row) in v["what_beta"].as_array().unwrap().iter().enumerate() {
        let got: Vec<String> = (i..6).map(|b| ntt::what_beta(i, b).to_hex()).collect();
        assert_eq!(got, strings(row), "what_beta row {i}");
    }
    for vec in v["vectors"].as_array().unwrap() {
        let msg = ks(&vec["message"]);
        let r = vec["log_inv_rate"].as_u64().unwrap() as usize;
        assert_eq!(hexes(&ntt::encode(&msg, r)), strings(&vec["codeword"]));
        assert_eq!(
            hexes(&ntt::encode_naive(&msg, r)),
            strings(&vec["codeword"])
        );
    }
}

#[test]
fn ring_switch_vector() {
    let v = load("ring_switch.json");
    let ell = v["ell"].as_u64().unwrap() as usize;
    let raw = bytes_from_hex(v["bits"].as_str().unwrap());
    let bits: Vec<bool> = (0..1 << ell)
        .map(|i| (raw[i / 8] >> (i % 8)) & 1 == 1)
        .collect();
    let r = ks(&v["point"]);
    let y = k(&v["value"]);
    assert_eq!(hexes(&rsw::pack(&bits)), strings(&v["packed"]));

    let label = v["transcript_label"].as_str().unwrap().as_bytes();
    let mut tr = Transcript::new_default(label);
    let (proof, r_s, out_v) = rsw::rs_prove(&bits, &r, y, &mut tr);
    assert_eq!(hexes(&proof.s), strings(&v["s"]));
    let msgs: Vec<Vec<String>> = proof.sumcheck.round_msgs.iter().map(|m| hexes(m)).collect();
    let expect_msgs: Vec<Vec<String>> = v["sumcheck_msgs"]
        .as_array()
        .unwrap()
        .iter()
        .map(strings)
        .collect();
    assert_eq!(msgs, expect_msgs);
    assert_eq!(hexes(&r_s), strings(&v["r_s"]));
    assert_eq!(out_v.to_hex(), v["v"].as_str().unwrap());

    // The verifier on the vector's own proof yields the same (r_s, v).
    let vec_proof = rsw::RingSwitchProof {
        s: ks(&v["s"]),
        sumcheck: SumcheckProof {
            round_msgs: v["sumcheck_msgs"]
                .as_array()
                .unwrap()
                .iter()
                .map(ks)
                .collect(),
        },
    };
    let mut vt = Transcript::new_default(label);
    let (r_s2, v2) = rsw::rs_verify(&r, y, &vec_proof, &mut vt).unwrap();
    assert_eq!(hexes(&r_s2), strings(&v["r_s"]));
    assert_eq!(v2.to_hex(), v["v"].as_str().unwrap());
}

#[test]
fn ligerito_vectors() {
    let v = load("ligerito.json");
    for vec in v["vectors"].as_array().unwrap() {
        let p = LigeritoParams::new(
            vec["n"].as_u64().unwrap() as usize,
            usizes(&vec["ks"]),
            usizes(&vec["rs"]),
            usizes(&vec["ts"]),
        );
        let pcs = LigeritoPCS::new(p);
        let tab = ks(&vec["table"]);
        let label = vec["transcript_label"].as_str().unwrap().as_bytes();
        let mut tr = Transcript::new_default(label);
        let (cm, st) = Pcs::commit(&pcs, &tab, &mut tr);
        assert_eq!(to_hex(&cm.root), vec["root"].as_str().unwrap());
        let r = ks(&vec["point"]);
        let (y, pf) = Pcs::open(&pcs, &st, &r, &mut tr);
        assert_eq!(y.to_hex(), vec["value"].as_str().unwrap());
        let roots: Vec<String> = pf.roots.iter().map(|x| to_hex(x)).collect();
        assert_eq!(roots, strings(&vec["next_roots"]));
        assert_eq!(hexes(&pf.final_poly), strings(&vec["final"]));
        let proof_bytes = pf.to_bytes();
        assert_eq!(
            proof_bytes.len(),
            vec["proof_len"].as_u64().unwrap() as usize
        );
        assert_eq!(
            to_hex(&Hasher::Sha256.digest(&proof_bytes)),
            vec["proof_bytes_sha256"].as_str().unwrap()
        );
        // And the proof verifies.
        let mut tv = Transcript::new_default(label);
        Pcs::absorb_commitment(&pcs, &cm, &mut tv);
        Pcs::verify(&pcs, &cm, &r, y, &pf, &mut tv).unwrap();
    }
}
